"""Local-only C-F1 bridge secret; generated by backend, read by Forge.

Not an Ollama/Qwen API key. Never ship or log this credential. Bridge endpoint
continues to reject non-loopback clients, irrespective of the secret.
"""
import os
from pathlib import Path
import re
import secrets
import stat

_TOKEN_RE = re.compile(r"[0-9a-f]{64}\Z")
_FILE_NAME = "cplus-f1.secret"


def secret_path() -> Path:
    override = os.environ.get("NPCORTEX_CPLUS_F1_SECRET_FILE", "").strip()
    if override:
        path = Path(override).expanduser()
        if not path.is_absolute():
            raise ValueError("NPCORTEX_CPLUS_F1_SECRET_FILE must be absolute")
        return path
    if os.name == "nt":
        base = Path(os.environ.get("LOCALAPPDATA") or Path.home() / "AppData" / "Local")
    else:
        config = os.environ.get("XDG_CONFIG_HOME", "")
        base = Path(config) if config and Path(config).is_absolute() else Path.home() / ".config"
    return base / "NPCortex" / "bridge" / _FILE_NAME


def _read_file(path: Path) -> str:
    if path.is_symlink():
        raise ValueError("C-F1 local secret cannot be a symlink")
    info = path.stat()
    if not stat.S_ISREG(info.st_mode):
        raise ValueError("C-F1 local secret must be a regular file")
    if os.name != "nt" and (stat.S_IMODE(info.st_mode) & 0o077):
        raise PermissionError("C-F1 secret is accessible to other users; restrict to mode 0600")
    if info.st_size > 128:
        raise ValueError("C-F1 local secret exceeds size limit")
    value = path.read_bytes().decode("ascii").strip()
    if not _TOKEN_RE.fullmatch(value):
        raise ValueError("C-F1 local secret is invalid; it will not be replaced automatically")
    return value


def read_secret() -> str:
    """Get manual override or previously created shared local secret.

    Called for each diagnostic request; empty result means fail closed.
    """
    override = os.environ.get("NPCORTEX_CPLUS_F1_TOKEN", "")
    if override:  # An explicitly configured credential ALWAYS wins; no downgrade.
        return override
    try:
        return _read_file(secret_path())
    except (OSError, ValueError, UnicodeError):
        return ""


def initialize_secret() -> str:
    """Backend startup: create private shared credential once, never overwrite.

    Forge reads, but never generates, the same credential. Using exclusive file
    creation prevents concurrent backend startups from replacing each other's key.
    If an existing file is partial/corrupt, fail closed rather than silently rotate.
    """
    override = os.environ.get("NPCORTEX_CPLUS_F1_TOKEN", "")
    if override:
        if len(override) < 24 or len(override) > 512 or "\n" in override or "\r" in override:
            raise ValueError("NPCORTEX_CPLUS_F1_TOKEN must be 24-512 header-safe characters")
        return "manual override"
    path = secret_path()
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    if path.exists() or path.is_symlink():
        _read_file(path)  # fail closed on invalid/unsafe existing file
        return "existing private file"
    value = secrets.token_hex(32) + "\n"
    try:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError:
        _read_file(path)
        return "existing private file"
    # Partial creation is never repaired automatically; operator can inspect it.
    with os.fdopen(fd, "wb") as stream:
        stream.write(value.encode("ascii"))
        stream.flush()
        os.fsync(stream.fileno())
    return "new private file"
